(function(){
'use strict';
const KEY='nawaf-hq-v5',terminal=new Set(['BLOCKED_BY_TOOL','BLOCKED','PAUSED']);let writing=false;
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function ensureBriefs(){if(writing)return;const s=read();s.secretaryBriefs=Array.isArray(s.secretaryBriefs)?s.secretaryBriefs:[];s.secretarySeen=Array.isArray(s.secretarySeen)?s.secretarySeen:[];let changed=false;for(const t of (s.tasks||[])){if(!terminal.has(t.status))continue;const key=`${t.id}:${t.status}:${t.lastRunAt||t.executionFinishedAt||''}`;if(s.secretarySeen.includes(key))continue;const e=(s.employees||[]).find(x=>x.id===t.employeeId),p=(s.projects||[]).find(x=>x.id===t.projectId);s.secretaryBriefs.unshift({id:'sectruth'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),key,taskId:t.id,status:t.status,projectId:t.projectId||'',title:t.title,employee:e?.name||'موظف AI',project:p?.name||'الشركة',result:t.blockedReason||'توقف التنفيذ بدون ادعاء نجاح.',at:new Date().toISOString(),read:false});s.secretarySeen.unshift(key);changed=true}if(changed){s.secretaryBriefs=s.secretaryBriefs.slice(0,80);s.secretarySeen=s.secretarySeen.slice(0,250);writing=true;localStorage.setItem(KEY,JSON.stringify(s));writing=false;window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:'secretary-truth'}}))}}
function relabel(){const s=read();for(const article of document.querySelectorAll('.exec-briefs article')){const title=article.querySelector('h4')?.textContent?.trim(),t=(s.tasks||[]).find(x=>x.title===title);if(!t||!terminal.has(t.status))continue;const label=article.querySelector('header span');if(label)label.textContent=t.status==='BLOCKED_BY_TOOL'?'أداة ناقصة — لا يحتاج قرارك':t.status==='PAUSED'?'متوقف مؤقتًا — لا يحتاج قرارك':'فشل التنفيذ';article.dataset.truthStatus=t.status}}
let timer;function run(){clearTimeout(timer);timer=setTimeout(()=>{ensureBriefs();relabel()},80)}
new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',run);setInterval(run,5000);run();
})();
